<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAppStore } from '../stores/app'; import { api } from '../api';
const props=defineProps<{mode:'login'|'register'|'forgot'}>(),store=useAppStore(),router=useRouter(),busy=ref(false),error=ref(''),message=ref('');
const form=reactive({account:'',username:'',nickname:'',email:'',phone:'',password:'',emailCode:'',smsCode:'',captchaText:'',newPassword:''}); const title=computed(()=>props.mode==='login'?'登录':props.mode==='register'?'创建账号':'找回密码');
const captcha=reactive({id:'',image:''});
const emailEnabled=computed(()=>store.settings['auth.register.email']!==false);
const smsEnabled=computed(()=>store.settings['auth.register.sms']===true);
const agreementOpen=ref(false),agreed=ref(false),scrolledToBottom=ref(false); const agreementText=computed(()=>String(store.settings['site.userAgreement']||''));
async function loadCaptcha(){try{const res=await api<{data:{captchaId:string,image:string}}>('/api/auth/captcha');captcha.id=res.data.captchaId;captcha.image=res.data.image}catch(e){error.value=(e as {message:string}).message}}
onMounted(()=>{if(props.mode!=='login')loadCaptcha();if(!store.loaded)void store.bootstrap()});
function onAgreementScroll(e:Event){const el=e.target as HTMLDivElement;scrolledToBottom.value=el.scrollTop+el.clientHeight>=el.scrollHeight-8}
function confirmAgreement(){agreed.value=true;agreementOpen.value=false;void submit()}
async function submit(){if(props.mode==='register'&&!agreed.value){agreementOpen.value=true;return}busy.value=true;error.value='';try{if(props.mode==='login'){await store.login(form.account,form.password);router.push('/')}else if(props.mode==='register'){await api('/api/auth/register',{method:'POST',body:JSON.stringify({username:form.username,nickname:form.nickname,email:form.email||undefined,phone:form.phone||undefined,password:form.password,emailCode:form.emailCode||undefined,smsCode:form.smsCode||undefined})});message.value='注册成功，请登录';setTimeout(()=>router.push('/login'),800)}else{await api('/api/auth/reset-password',{method:'POST',body:JSON.stringify({channel:'EMAIL',target:form.email,code:form.emailCode,newPassword:form.newPassword})});message.value='密码已重置';}}catch(e){error.value=(e as {message:string}).message}finally{busy.value=false}}
async function sendCode(channel:'EMAIL'|'SMS'){error.value='';message.value='';if(!form.captchaText){error.value='请先输入图形验证码';return}try{const target=channel==='EMAIL'?form.email:form.phone;await api(channel==='EMAIL'?'/api/auth/email/send-code':'/api/auth/sms/send-code',{method:'POST',body:JSON.stringify({[channel==='EMAIL'?'email':'phone']:target,purpose:props.mode==='forgot'?'RESET_PASSWORD':'REGISTER',captchaId:captcha.id,captchaText:form.captchaText})});message.value=channel==='EMAIL'?'验证码已发送，请检查邮箱':'验证码已发送，请检查短信'}catch(e){error.value=(e as {message:string}).message;loadCaptcha();form.captchaText=''}}
</script>
<template><div class="auth-wrap panel"><h1>{{title}}</h1><form class="form" @submit.prevent="submit"><template v-if="mode==='login'"><label>账号<input v-model="form.account" class="input" autocomplete="username" required placeholder="用户名 / 邮箱 / 手机号"></label><label>密码<input v-model="form.password" class="input" type="password" autocomplete="current-password" required></label></template><template v-else-if="mode==='register'"><label>用户名<input v-model="form.username" class="input" required minlength="3"></label><label>昵称<input v-model="form.nickname" class="input" required></label><label v-if="emailEnabled">邮箱<input v-model="form.email" class="input" type="email"></label><label v-if="smsEnabled">手机号<input v-model="form.phone" class="input"></label><label>密码<input v-model="form.password" class="input" type="password" required><small>密码规则由平台管理员统一配置，服务端会再次校验。</small></label><label>图形验证码<div class="search"><img class="captcha-img" :src="captcha.image" alt="图形验证码" title="点击刷新" @click="loadCaptcha"><input v-model="form.captchaText" class="input" placeholder="输入图片中的英文字母" autocomplete="off"></div></label><label v-if="emailEnabled">邮箱验证码<div class="search"><input v-model="form.emailCode" class="input"><button type="button" class="button" @click="sendCode('EMAIL')">发送</button></div></label><label v-if="smsEnabled">手机验证码<div class="search"><input v-model="form.smsCode" class="input"><button type="button" class="button" @click="sendCode('SMS')">发送</button></div></label></template><template v-else><label>邮箱<input v-model="form.email" class="input" type="email" required></label><label>图形验证码<div class="search"><img class="captcha-img" :src="captcha.image" alt="图形验证码" title="点击刷新" @click="loadCaptcha"><input v-model="form.captchaText" class="input" placeholder="输入图片中的英文字母" autocomplete="off"></div></label><label>验证码<div class="search"><input v-model="form.emailCode" class="input" required><button type="button" class="button" @click="sendCode('EMAIL')">发送</button></div></label><label>新密码<input v-model="form.newPassword" type="password" class="input" required></label></template><p v-if="error" class="error">{{error}}</p><p v-if="message" class="success">{{message}}</p><button class="button primary-button" :disabled="busy">{{busy?'请稍候…':title}}</button><div><router-link v-if="mode==='login'" to="/forgot-password" class="muted">忘记密码</router-link><router-link v-if="mode!=='login'" to="/login" class="muted"> 返回登录</router-link></div></form><div v-if="agreementOpen" class="modal-mask" @click.self="agreementOpen=false"><div class="modal-card"><h3>用户协议</h3><div class="agreement-box" @scroll="onAgreementScroll">{{agreementText}}</div><p v-if="!scrolledToBottom" class="muted">请阅读协议内容并滚动到底部</p><label><span><input v-model="agreed" type="checkbox" :disabled="!scrolledToBottom"> 我已阅读并同意《用户协议》</span></label><div class="actions"><button type="button" class="button" @click="agreementOpen=false">取消</button><button type="button" class="button primary-button" :disabled="!agreed" @click="confirmAgreement">同意并继续注册</button></div></div></div></div></template>
